function easeOutQuart(x) {
	return 1 - Math.pow(1 - x, 4);
}

function drawBridge(x1, y1, d1, x2, y2, d2, dst) {
	let r = dst / 2;

	let r1 = d1 / 2;
	let r2 = d2 / 2;
	let R1 = r1 + r;
	let R2 = r2 + r;

	let dx = x2 - x1;
	let dy = y2 - y1;
	let d = sqrt(dx * dx + dy * dy);

	if (d > R1 + R2) {
		return;
	}

	let dirX = dx / d;
	let dirY = dy / d;

	let a = (R1 * R1 - R2 * R2 + d * d) / (2 * d);
	let underRoot = R1 * R1 - a * a;
	if (underRoot < 0) return;
	let h = sqrt(underRoot);


	let midX = x1 + dirX * a;
	let midY = y1 + dirY * a;

	let perpX = -dirY * h;
	let perpY = dirX * h;

	let cx1 = midX + perpX;
	let cy1 = midY + perpY;

	let cx2 = midX - perpX;
	let cy2 = midY - perpY;

	if (dist(cx1, cy1, cx2, cy2) < r * 2) {
		return;
	}

	let ang1 = atan2(y1 - cy1, x1 - cx1);
	let ang2 = atan2(y2 - cy1, x2 - cx1);
	let ang3 = atan2(y2 - cy2, x2 - cx2);
	let ang4 = atan2(y1 - cy2, x1 - cx2);

	if (ang2 < ang1) {
		ang2 += TAU;
	}
	beginShape();
	for (let i = ang1; i < ang2; i += TAU / 180) {
		vertex(cx1 + r * cos(i), cy1 + r * sin(i));
	}

	if (ang4 < ang3) {
		ang4 += TAU;
	}
	for (let i = ang3; i < ang4; i += TAU / 180) {
		vertex(cx2 + r * cos(i), cy2 + r * sin(i));
	}
	endShape();
}

class Mover {
	constructor(x, y, d, clr) {
		this.x = x;
		this.y = y;
		this.d = d;
		this.clr = clr;
		this.t1 = 75;
		this.init();
	}

	show() {
		noStroke();
		fill('#fafafa');
		circle(this.x, this.y, this.d);
	}

	move() {
		this.t++;
		if (0 < this.t && this.t < this.t1) {
			let n = norm(this.t, 0, this.t1 - 1);
			this.x = lerp(this.x0, this.x1, easeOutQuart(n));
			this.y = lerp(this.y0, this.y1, easeOutQuart(n));
		}

		if (this.t > this.t1) {
			this.init();
		}
	}

	init() {
		this.x0 = this.x;
		this.y0 = this.y;
		do {
			let a = random(TAU);
			let r = width * 0.3;
			this.x1 = this.x + r * cos(a);
			this.y1 = this.y + r * sin(a);
		} while (this.x1 < 0 || width < this.x1 || this.y1 < 0 || height < this.y1);
		this.t = 0;
	}

	run() {
		this.show();
		this.move();
	}
}

